<script>
document.addEventListener('DOMContentLoaded',()=>{const p=document.getElementById('payPatient'),t=document.getElementById('payTarget'),ty=document.getElementById('targetType'),id=document.getElementById('targetId'),bal=document.getElementById('payBalance'),amt=document.getElementById('payAmount'),canvas=bootstrap.Offcanvas.getOrCreateInstance('#recordPayment');let wanted='{{ request('target_type') }}:{{ request('target_id') }}';async function load(open=false){ty.value=id.value='';t.disabled=true;t.innerHTML='<option>Loading…</option>';if(!p.value){t.innerHTML='<option>Select a patient first</option>';return}try{let r=await fetch(`{{ route('staff.payments.payable-items') }}?patient_id=${p.value}`,{headers:{Accept:'application/json'}}),data=await r.json();t.innerHTML='<option value="">Select payable item</option>';data.items.forEach(x=>{let label=x.balance===null?'No final total agreed':`₱${Number(x.balance).toLocaleString(undefined,{minimumFractionDigits:2})}`;let o=new Option(`${x.label} · ${label}`,`${x.type}:${x.id}`);o.dataset.balance=x.balance===null?'unknown':x.balance;t.add(o)});t.disabled=false;if(wanted&&[...t.options].some(o=>o.value===wanted)){t.value=wanted;t.dispatchEvent(new Event('change'));wanted=''}if(open)canvas.show()}catch(e){t.innerHTML='<option>Unable to load balances</option>'}}p.addEventListener('change',()=>load());t.addEventListener('change',()=>{let a=t.value.split(':'),raw=t.selectedOptions[0]?.dataset.balance,due=Number(raw||0);ty.value=a[0]||'';id.value=a[1]||'';bal.textContent=raw==='unknown'?'Not determinable — no total agreed':'₱'+due.toLocaleString(undefined,{minimumFractionDigits:2});if(raw==='unknown')amt.removeAttribute('max');else amt.max=due||'';t.setCustomValidity('')});document.addEventListener('click',e=>{const b=e.target.closest('.js-plan-pay');if(!b)return;p.value=b.dataset.patient;wanted=b.dataset.target;load(true)});document.getElementById('paymentForm').onsubmit=e=>{if(!id.value){e.preventDefault();t.setCustomValidity('Select a payable item.');t.reportValidity();return}let b=document.getElementById('paySubmit');b.disabled=true;b.textContent='Recording…'};if(p.value)load({{ ((isset($errors)&&$errors->any())||request()->boolean('open_record'))?'true':'false' }});else if({{ ((isset($errors)&&$errors->any())||request()->boolean('open_record'))?'true':'false' }})canvas.show()});
</script>
